\label{main theorem first system}
    Let $M>N$ be large enough. We assume that $\Phi_0,\ldots,\Phi_I$ satisfy the first model system on the background $\big(\mathcal{M},g\big),$ with $\sigma=1$ in \eqref{equation for Phi i}. We also assume that the sphere $\big(S^n,\slashed{g}_0\big)$ satisfies for some $C_1>0:$
    \[\big\|\slashed{Riem}(\slashed{g}_0)\big\|_{H^{M}(S^n)}\leq C_1.\]
    For all $\tau\in(0,1],$ we define the energy of the solution on $S_{\tau}$ to be:
    \[\mathcal{E}_I(\tau)=\tau^2\big\|\nabla_{\tau}\nabla^M\Phi_0\big\|^2_{H^{1/2}}+\tau^2\big\|\nabla^M\Phi_0\big\|^2_{H^{3/2}}+\sum_{i=1}^I\Big(\tau\big\|\nabla_{\tau}\nabla^M\Phi_i\big\|^2_{H^{1/2}}+ \tau\big\|\nabla^{M+1}\Phi_i\big\|^2_{H^{1/2}}+\big\|\Phi_i\big\|^2_{H^{M+1}}\Big).\]
    We define the asymptotic data norm and the inhomogeneous norm as:
    \[\mathcal{D}_I=\big\|\mathcal{O}\big\|^2_{H^{M+1}}+\big\|\mathfrak{h}\big\|^2_{H^{M+1}}+\sum_{i=1}^I\big\|\Phi_i^0\big\|^2_{H^{M+1}},\ \mathcal{F}_I(\tau)=\sum_{m=0}^{M}\sum_{i=0}^I\int_0^{\tau}\big\|F_m^i\big\|_{L^2}^2d\tau'+\sum_{i=0}^I\int_0^{\tau}\tau'\big\|F_M^i\big\|_{H^{1/2}}^2d\tau'.\]
    The solution of the first model system satisfies the estimates for some constant $C_I=C_I\big(M,C_0,C_1\big)>0$:
    \begin{equation}\label{main estimate first model system}
        \mathcal{E}_I(\tau)\leq C_I\mathcal{D}_I+C_I\mathcal{F}_I(\tau),
    \end{equation}
    \begin{equation}\label{practical estimate first model system}
        \big\|\Phi_0\big\|^2_{H^{M+1}}\leq C_I\mathcal{D}_I+C_I\mathcal{F}_I(\tau)+C_I|\log\tau|^2\big\|\mathcal{O}\big\|^2_{H^{M+1}}.
    \end{equation}

\label{main theorem second system}    
    Let $M>N$ be large enough. We assume that $\Phi_0,\ldots,\Phi_I$ satisfy the second model system on the background $\big(\mathcal{M},g\big),$ with $\sigma=2$ in \eqref{equation for Phi i}. We also assume that on $S_{1}=\{1\}\times S^n$ we have for some $C_2>0:$
    \[\big\|\psi\big\|_{H^{M+1}(S_{1})}\leq C_2.\]
    For all $\tau\in(0,1],$ we denote by $\mathcal{E}_{II}(\tau)$ the energy of the solution on $S_{\tau}$, which is defined in detail in~\eqref{definition of E II}. We have schematically at top order with respect to angular derivatives:
    \[\mathcal{E}_{II}(\tau)=\tau^2\big\|\Phi_0\big\|_{H^{M+3/2}}^2+\tau^2\big\|\nabla_{\tau}\nabla^M\Phi_0\big\|_{H^{1/2}}^2+\sum_{i=1}^I\big\|\Phi_i\big\|_{H^{M+3/2}}^2+\sum_{i=1}^I\big\|\nabla_{\tau}\nabla^M\Phi_i\big\|_{H^{1/2}}^2+\ldots\]
    We define the asymptotic data norm and the inhomogeneous norm as:
    \[\mathcal{D}_{II}=\sum_{i=0}^I\big\|\Phi_i\big\|_{H^{M+3/2}(S_{1})}^2+\sum_{i=0}^I\big\|\nabla_{\tau}\Phi_i\big\|_{H^{M+1/2}(S_{1})}^2,\ \mathcal{F}_{II}(\tau)=\sum_{i=0}^I\sum_{m=0}^{M}\int_{\tau}^1\tau'\big\|F_m^i\big\|_{H^{1/2}}^2d\tau'.\]
    The solution of the second model system satisfies the estimate for some constant $C_{II}=C_{II}\big(M,C_0,C_2\big)>0$:
    \begin{equation}\label{main estimate second model system}
        \mathcal{E}_{II}(\tau)\leq C_{II}\mathcal{D}_{II}+C_{II}\mathcal{F}_{II}(\tau).
    \end{equation}
    Moreover, the asymptotic data at $\mathcal{I}^-$ given by $\Phi_i^0,\ \mathcal{O},$ and $\mathfrak{h}$ satisfies the estimates:
    \begin{equation}\label{main estimate asymptotic data}
        \big\|\mathcal{O}\big\|_{H^{M+1}}^2+\sum_{i=1}^I\big\|\Phi_i^0\big\|^2_{H^{M+1}}\leq C_{II}\mathcal{D}_{II}+C_{II}\mathcal{F}_{II}(0),
    \end{equation}
    \begin{equation}\label{main estimate asymptotic data h}
        \big\|\mathfrak{h}\big\|_{H^{M+1}}^2\leq C\Big(C_{II},\big\|\slashed{Riem}(\slashed{g}_0)\big\|_{H^{M}}\Big)\cdot\Big(\mathcal{D}_{II}+\mathcal{F}_{II}(0)+\big\|h\big\|_{L^2}^2\Big).
    \end{equation}

\label{main theorem of main}
    For any even integer $n\geq4,$ we have a scattering theory for asymptotically de Sitter vacuum solutions determined by small data. For any $M>0$ large enough there exists $\varepsilon_0>0$ small enough, such that for any $0<\varepsilon\leq\varepsilon_0$ we have:
    \begin{enumerate}
    \item\textit{Existence and uniqueness of scattering states:} for any $\varepsilon$-small asymptotic data of order $M$ at $\mathcal{I}^-$ or $\mathcal{I}^+$ given by $\Sigma\big(\slashed{g}_0,h\big)\in B_{\varepsilon}^M\big(\Sigma_{dS}\big)$, there exists a unique smooth global solution $\big(\mathcal{M},g\big)$ of the form (\ref{general form for metric g}) to the Einstein vacuum equations (\ref{Einstein vacuum eq}) which remains quantitatively close to the de Sitter metric; 
    \item\textit{Asymptotic completeness:} any smooth solution of the Einstein vacuum equations (\ref{Einstein vacuum eq}) of the form (\ref{general form for metric g}), which is quantitatively close to the de Sitter metric at a finite time $\tau,$ exists globally and induces scattering data $\big(\slashed{g}_0,h\big)$ at $\mathcal{I}^-$ and $\big(\underline{\slashed{g}_0},\underline{h}\big)$ at $\mathcal{I}^+;$
    \item\textit{Existence of a scattering map with quantitative estimates:} there exists a constant $C_M>0$ independent of $\varepsilon,$ such that we have a well-defined scattering map taking the asymptotic data at $\mathcal{I}^-$ to asymptotic data at $\mathcal{I}^+:$
    \begin{equation}\label{def of scattering map intro}
        \mathcal{S}:B_{\varepsilon}^M\big(\Sigma_{dS}\big)\rightarrow B_{C_M\varepsilon}^M\big(\Sigma_{dS}\big),\ \mathcal{S}\Big(\Sigma\big(\slashed{g}_0,h\big)\Big)=\Sigma\big(\underline{\slashed{g}_0},\underline{h}\big).
    \end{equation}
    The scattering map is locally invertible and locally Lipschitz at $\Sigma_{dS},$ satisfying the quantitative estimate:
    \begin{equation}\label{main estimate for S map intro}
        \Big\|\mathcal{S}\big(\Sigma(\slashed{g}_0,h)\big)\Big\|_M\leq C_M\Big\|\Sigma\big(\slashed{g}_0,h\big)\Big\|_M.
    \end{equation}
    This estimate is sharp and avoids any "derivative loss", in the sense that we use the same Sobolev-type norm of order $M$ to measure the smallness of asymptotic data at $\mathcal{I}^{\pm}.$
\end{enumerate}

\label{Litt Paley lemma}
The LP projection operators satisfy the following bounds for $k\geq 0$:
\begin{align}
    [\nabla_t,P_k]&=\frac{t}{2^{2k-1}}[\nabla_4,P_k],\text{ where } t=2^{k}\tau\label{LP est 1}\\
    \big\|[\nabla^m,P_k]F\big\|_{L^2}&\lesssim2^{-k} C\big(\|\slashed{Riem}\|_{H^{m-1}}\big)\cdot\big\|F\big\|_{H^{m-1}}\label{LP est 2}\\
    \big\|\nabla[\nabla^m,P_k]F\big\|_{L^2}&\lesssim2^{-k} C\big(\|\slashed{Riem}\|_{H^{m}}\big)\cdot\big\|F\big\|_{H^{m}}\label{LP est 3}\\
    \big\|[\nabla_4,P_k]F\big\|_{L^2}&\lesssim\big\|F\big\|_{L^2}\label{LP est 4}\\
    \big\|\nabla[\nabla_4,P_k]F\big\|_{L^2}&\lesssim\big\|F\big\|_{H^1}\label{LP est 5}\\
    \big\|[P_k,G]F\big\|_{L^2}&\lesssim2^{-k}\big\|G\big\|_{W^{2,\infty}}\big\|F\big\|_{L^2}\label{LP est 6}\\
    \big\|\nabla[P_k,G]F\big\|_{L^2}&\lesssim\big\|G\big\|_{W^{2,\infty}}\big\|F\big\|_{L^2}.\label{LP est 7}
\end{align}

\label{fractional LP bounds}
    We have the following estimates for $k\geq 0$:
    \begin{equation}\label{fractional LP est 1}
    \big\|[\nabla_4,P_k]\nabla F\big\|_{L^2}\lesssim2^{k/2}\big\|F\big\|_{H^{1/2}}
\end{equation}
\begin{equation}\label{fractional LP est 2}
    \big\|\nabla[\nabla_4,P_k] F\big\|_{L^2}\lesssim2^{k/2}\big\|F\big\|_{H^{1/2}}.
\end{equation}

For any $k\geq0,$ and $\delta>0$, we have the inequality:
    \begin{equation}\label{ref Poincarey}
    \big\|P_kF\big\|_{L^2}^2\lesssim\frac{1}{\delta}2^{-2k}\big\|\nabla P_kF\big\|_{L^2}^2+\delta\sum_{0\leq l<k}2^{-9k+7l}\big\|\nabla P_lF\big\|_{L^2}^2+\delta^{-1}2^{-4k}\big\|F\big\|_{L^2}^2.
\end{equation}

\label{R k lemma} Let $F$ be any smooth tensor on $S_0$. We extend $R_kF$ to $(0,1]\times S^n$ to be independent of $\tau.$ We also denote $t=2^k\tau.$ Then, for any $k\geq0$ we have:
    \begin{align}
        \big\|\Delta_{\slashed{g}_{\tau}} R_kF\big\|_{L^2}&\lesssim2^{k}\big\|\underline{P}_kF\big\|_{H^1}\label{Rk est 1}\\
        \big\|\nabla R_kF\big\|_{L^2}&\lesssim\big\|\underline{P}_kF\big\|_{H^1}\label{Rk est 2}\\
        2^{k}\big\|R_kF\big\|_{L^2}&\lesssim \big\|\underline{P}_kF\big\|_{H^1}\label{Rk est 3}\\
        \big\|\nabla_tR_kF\big\|_{L^2}&\lesssim2^{-3k}t\big\|\underline{P}_kF\big\|_{H^1}\label{Rk est 4}\\
        \big\|\nabla\nabla_tR_kF\big\|_{L^2}&\lesssim2^{-2k}t\big\|\underline{P}_kF\big\|_{H^1}.\label{Rk est 5}
    \end{align}

\label{difference of projections lemma}
    We consider $F$ to be a smooth tensor on $S_0,$ extended to be independent of $\tau.$ Denote by $^{(\slashed{g}_{0})}P_k$ the projection with respect to $\big(S^n_{0},\slashed{g}_{0}\big)$ and by $^{(\slashed{g}_{\tau})}P_k$ the projection with respect to $\big(S^n_{\tau},\slashed{g}_{\tau}\big)$. Then we have the estimate for any $s\geq0,\ k\geq0$:
    \begin{equation}\label{difference of Pk}
        \big\|\big(\ ^{(\slashed{g}_{0})}P_k-\ ^{(\slashed{g}_{\tau})}P_k\big)F\big\|_{H^{s}}\lesssim_s\tau^2\big\|F\big\|_{H^{s+2}}.
    \end{equation}

