    \[\big\|\tau P_k\nabla_{\tau}\xi\big\|_{L^2}^2+\big\|\tau\nabla P_k\xi\big\|_{L^2}^2\lesssim_X2^{-3k}\mathcal{D}_{II}+2^{-3k}\int_{\tau}^{1}(\tau')^2\big\|F_M'\big\|_{L^2}^2d\tau'.\]

\label{prelim low freq singular proposition}
    For any $0\leq\tau<X2^{-k-1}\leq1$ we have the low frequency regime estimate:
    \begin{align*}
        \big\|\tau P_k\nabla_{\tau}\xi\big\|_{L^2}^2+\big\|\tau\nabla P_k\xi\big\|_{L^2}^2\lesssim &X^22^{-2k}\Big(\big\|P_k\nabla_{\tau}\xi\big\|^2_{L^2}+\big\|\nabla P_k\xi\big\|^2_{L^2}\Big)\Big|_{\tau=X2^{-k-1}}+C_X2^{-3k}\mathcal{D}_{II}+\\
        &+C_X2^{-k}\int_{\tau}^{X2^{-k-1}}(\tau')^2\big\|P_kF_M'\big\|_{L^2}^2d\tau'+C_X2^{-3k}\int_{\tau}^{1}(\tau')^2\big\|F_M'\big\|_{L^2}^2d\tau'.
    \end{align*}

\label{improved high frequency estimate proposition}
    We denote by $\mathbf{1}_{k,\tau}$ the characteristic function of $\{1\geq\tau\geq X2^{-k-1}\},$ and we denote:
    \[a_k(\tau):=\tau\big\|P_k\nabla_{\tau}\xi\big\|^2_{L^2}+\frac{1}{\tau}\big\|P_k\xi\big\|^2_{L^2}+\tau\big\|\nabla P_k\xi\big\|^2_{L^2}.\]
    We have the improved high frequency estimate for any $\tau\in(0,1]$:
    \begin{equation}\label{optimal high frequency estimate}
        \sum_{\tau\geq X2^{-k-1}}2^ka_k(\tau)\mathbf{1}_{k,\tau}\lesssim \mathcal{D}_{II}+\int_{\tau}^1\tau'\big\|F_M'\big\|_{H^{1/2}}^2d\tau'.
    \end{equation}

\label{grwonwall type lemma}
    We consider the functions $u,A,b,c:\mathbb{N}\times[0,1]\rightarrow[0,\infty),$ which for all $k\geq x,\ \tau\in(0,1]$ satisfy the inequality:
    \begin{equation}\label{inequality assumption}
        u(k,\tau)\leq A(k,\tau)+b(k)\int_{\tau}^1\sum_{l=x}^{k-1}c(l,\tau')u(l,\tau')d\tau'
    \end{equation}
    Then, we have that for all $k\geq x,\ \tau\in(0,1]$:
    \begin{equation}\label{inequality conclusion}
        u(k,\tau)\leq A(k,\tau)+b(k)\int_{\tau}^1\sum_{l=x}^{k-1}c(l,\tau')A(l,\tau')\prod_{j=l+1}^{k-1}\bigg(1+\int_{\tau}^{\tau'}b(j)c(j,\tau'')d\tau''\bigg)d\tau'.
    \end{equation}

For all $k\geq x$ and $\tau\in[X2^{-k-1},1]$, we have the high frequency regime estimate:
    \begin{equation}\label{third schematic eq}
        2^ka_k(\tau)\mathbf{1}_{k,\tau}\lesssim A_k(\tau)+2^{-7k}\int_{\tau}^1\sum_{l=0}^{k-1}\frac{2^{5l}}{(\tau')^3}\cdot A_l(\tau')\mathbf{1}_{l,\tau'}d\tau'
    \end{equation}

\label{estimate for O proposition}
    The obstruction tensor $\mathcal{O}$ satisfies the estimate \eqref{estimate for O intro}:
    \[\big\|\mathcal{O}\big\|_{H^{M+1}}^2\lesssim \mathcal{D}_{II}+\mathcal{F}_{II}(0).\]

\label{lemma for the fourth intermediate term}
    We have the bound for all $\tau\in(0,X2^{-k-1}]$:
    \[\int_{\tau}^{X2^{-k-1}}2^{k}(2^k\tau')^3|\log(2^k\tau')|^2\sum_{l\geq k}\mathbf{1}_{l,\tau'}2^{-6(l-k)}\cdot2^la_l(\tau')d\tau'\lesssim\]\[\lesssim d_k+\tau^62^{6k}\cdot\big(\mathcal{D}_{II}+\mathcal{F}_{II}(\tau)\big)+\sum_{\tau<X2^{-m-1}\leq1}2^{-4|k-m|}\Big(E_m(X2^{-m-1})+I_m(X2^{-m-1})\Big)+\]\[+\widetilde{E}_k(X2^{-k-1})+\widetilde{I}_k(X2^{-k-1})+\sum_{l\geq k}2^{-6(l-k)}\bigg(\int_{\tau}^1e_l(\tau')d\tau'+\int_{\tau}^12^l\tau'\big\|P_lF_M'\big\|_{L^2}^2d\tau'\bigg)+2^{-k}\mathcal{F}_{II}(\tau).\]
